class Solution:
    def generateMatrix(self, n: int) -> list[list[int]]:
        ans = [[0] * n for _ in range(n)]
        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        r = c = d = 0
        for val in range(1, n * n + 1):
            ans[r][c] = val
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            if nr < 0 or nr >= n or nc < 0 or nc >= n or ans[nr][nc] != 0:
                d = (d + 1) % 4
                nr, nc = r + dirs[d][0], c + dirs[d][1]
            r, c = nr, nc
        return ans

